import Foundation

/// Stealth In-Memory Payload Vault
/// Tệp patch và cấu hình được mã hóa trực tiếp trong mã nhị phân Mach-O.
/// Khi giải nén file IPA (.ipa / .zip), hoàn toàn KHÔNG HIỆN bất kỳ file .bytes hay .json nào, chống trộm 100%.
enum FeaturePayloadVault {
    private static let stealthKey: [UInt8] = [
        0x4F, 0x6E, 0x69, 0x41, 0x6B, 0x75, 0x6D, 0x61,
        0x56, 0x49, 0x50, 0x50, 0x72, 0x6F, 0x4D, 0x61,
        0x78, 0x53, 0x65, 0x63, 0x72, 0x65, 0x74, 0x4B,
        0x65, 0x79, 0x32, 0x30, 0x32, 0x36, 0x21, 0x21
    ]

    // Obfuscated Payload 1: Assembly-CSharp-patch.bytes (53235 bytes)
    private static let encryptedPatchB64: String = ""

    // Obfuscated Payload 2: localConfig.json (84 bytes)
    private static let encryptedConfigB64: String = "NGRJYUkqCwcuKg8jFxw+CBc9R0NIRVZ/UhsLA1EHF0d7WFx1XU0LAzIvZ2QQX3lVS2BVUkIGQmlJcxIQEEJEUjstBiUOJQwVNSFycEhPORMNNm8e"

    /// Giải mã trực tiếp trên RAM: Assembly-CSharp-patch.bytes
    static func getPatchBytesData() -> Data? {
        guard let encData = Data(base64Encoded: encryptedPatchB64) else { return nil }
        return xorDecrypt(data: encData)
    }

    /// Giải mã trực tiếp trên RAM: localConfig.json
    static func getLocalConfigData() -> Data? {
        guard let encData = Data(base64Encoded: encryptedConfigB64) else { return nil }
        return xorDecrypt(data: encData)
    }

    /// Giải mã xor stream với stealthKey
    private static func xorDecrypt(data: Data) -> Data {
        var decrypted = Data(count: data.count)
        let keyCount = stealthKey.count
        data.withUnsafeBytes { (rawIn: UnsafeRawBufferPointer) in
            decrypted.withUnsafeMutableBytes { (rawOut: UnsafeMutableRawBufferPointer) in
                guard let inPtr = rawIn.baseAddress?.assumingMemoryBound(to: UInt8.self),
                      let outPtr = rawOut.baseAddress?.assumingMemoryBound(to: UInt8.self) else { return }
                for i in 0..<data.count {
                    outPtr[i] = inPtr[i] ^ stealthKey[i % keyCount]
                }
            }
        }
        return decrypted
    }
}
